args.command:
node -e '
const fs = require("fs");
const html = fs.readFileSync(".research/home.html", "utf8");
const css = fs.readFileSync(".research/globals.css", "utf8");

// Find where --brand-accent appears in css
const idx = css.indexOf("--brand-accent");
console.log("=== CSS around --brand-accent ===");
console.log(css.slice(Math.max(0, idx - 400), idx + 1200));

// Find SVGs or logo in HTML
const navMatch = html.match(/<header[\s\S]*?<\/header>/) || html.match(/<nav[\s\S]*?<\/nav>/);
console.log("=== HEADER/NAV ===");
if (navMatch) console.log(navMatch[0].slice(0, 3000));

// Find Hero section
const h1Idx = html.indexOf("<h1");
console.log("=== HERO HTML ===");
console.log(html.slice(Math.max(0, h1Idx - 1500), h1Idx + 3500));
'

