args.command:
curl -sL https://lumail.io/images/lumail-logo-light-128.webp -o .research/logo-light.webp && curl -sL https://lumail.io/images/lumail-logo-dark-128.webp -o .research/logo-dark.webp && node -e '
const fs = require("fs");
const css = fs.readFileSync(".research/globals.css", "utf8");
const html = fs.readFileSync(".research/home.html", "utf8");

// Find light mode variables (search for --background:)
let pos = 0;
while ((pos = css.indexOf("--background:", pos)) !== -1) {
  console.log("=== --background match at", pos, "===");
  console.log(css.slice(Math.max(0, pos - 100), pos + 1500));
  pos += 20;
}

// Find lumail-wordmark and marketing classes in css
const wmIdx = css.indexOf("lumail-wordmark");
if (wmIdx !== -1) {
  console.log("=== lumail-wordmark CSS ===");
  console.log(css.slice(Math.max(0, wmIdx - 200), wmIdx + 1500));
}
'

