curl -s "https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700;800&family=Geist+Mono:wght@400;500;600;700&family=Instrument+Serif:ital@0;1&family=Caveat:wght@600" -o .research/fonts/fonts.css && node -e '
const fs = require("fs");
const { execSync } = require("child_process");
const css = fs.readFileSync(".research/fonts/fonts.css", "utf8");
const blocks = css.split("@font-face").slice(1);
for (const b of blocks) {
  const fam = b.match(/font-family:\s*\x27([^\x27]+)\x27/)[1].replace(/\s+/g, "");
  const style = b.match(/font-style:\s*(\w+)/)[1];
  const weight = b.match(/font-weight:\s*(\d+)/)[1];
  const url = b.match(/url\((https:\/\/[^)]+\.ttf)\)/)[1];
  const out = `.research/fonts/${fam}-${weight}-${style}.ttf`;
  execSync(`curl -sL "${url}" -o "${out}"`);
  console.log("Saved", out);
}
' && ls -lh .research/fonts

