ffmpeg -y -i .research/logo-light.webp .research/logo-light.png 2>/dev/null && node -e '
const { createCanvas, GlobalFonts, loadImage } = require("@napi-rs/canvas");
GlobalFonts.registerFromPath(".research/fonts/Geist-400-normal.ttf", "GeistRegular");
GlobalFonts.registerFromPath(".research/fonts/Geist-500-normal.ttf", "GeistMedium");
GlobalFonts.registerFromPath(".research/fonts/Geist-600-normal.ttf", "GeistSemiBold");
GlobalFonts.registerFromPath(".research/fonts/Geist-700-normal.ttf", "GeistBold");
GlobalFonts.registerFromPath(".research/fonts/Geist-800-normal.ttf", "GeistExtraBold");
GlobalFonts.registerFromPath(".research/fonts/GeistMono-400-normal.ttf", "GeistMono");
GlobalFonts.registerFromPath(".research/fonts/GeistMono-500-normal.ttf", "GeistMonoMedium");
GlobalFonts.registerFromPath(".research/fonts/GeistMono-600-normal.ttf", "GeistMonoSemiBold");
GlobalFonts.registerFromPath(".research/fonts/InstrumentSerif-400-italic.ttf", "InstrumentSerifItalic");
GlobalFonts.registerFromPath(".research/fonts/InstrumentSerif-400-normal.ttf", "InstrumentSerif");
GlobalFonts.registerFromPath(".research/fonts/Caveat-600-normal.ttf", "Caveat");

(async () => {
  const img = await loadImage(".research/logo-light.png");
  const canvas = createCanvas(1920, 1080);
  const ctx = canvas.getContext("2d");
  const t0 = Date.now();
  for (let i = 0; i < 60; i++) {
    ctx.fillStyle = "#f8f7f4";
    ctx.fillRect(0, 0, 1920, 1080);
    ctx.drawImage(img, 100, 100, 91, 91);
    ctx.font = "64px GeistSemiBold";
    ctx.fillStyle = "#1a1614";
    ctx.fillText("The AI Tool that will make you love e-mail marketing", 220, 160);
    const raw = canvas.data();
  }
  console.log("60 frames rendered + buffer extracted in", Date.now() - t0, "ms");
})();
'

